/*
 * ===== #WCCC_Flip =====
 * Made for the weekly creative code challenge hosted by @Sableraph 
 * Discord: discord.gg/h9yJJYwy
 * Twitch: twitch.tv/Sableraph
 * 
 * Hey raph and chat o/
 * This sketch is one of those that came together pretty much exactly as i pictured it in my head.
 * The thing im most proud of about this sketch is that it is not actually 3D in the way that it does not use the webgl mode to enable drawing in 3 dimensions.
 * instead i got to make use of my limited linear algebra knowledge from uni to cobble together a pseudo 3d looking thing by skewing the right things in the right way
 * it is by no means elegant but it brought me infinitely more joy to figure out than just drawing some turning squares and let p5 figure out all the 3d stuff
 */

p5.disableFriendlyErrors = false;

// colors gruvbox theme https://github.com/morhetz/gruvbox
const background_dark = '#282828';
const colors_dark = ['#d79921', '#d65d0e', '#cc241d', '#b16286', '#458588', '#689d6a', '#98971a'];

const background_light = "#ebdbb2";
const colors_light = ['#b57614', '#af3a03', '#9d0006', '#8f3f71', '#076678', '#427b58', '#79740e'];


const cellSize = 120;
let cellsX;
let cellsY;

let offsetX = 0;
let offsetY = 0;
let i_hat;
let j_hat;
let k_hat;

let squares = []

function setup() {
	describe("a plane of small squares scrolls over the screen from the right to the left. towards the left of the screen the squares flip over revealing their color")

	i_hat = createVector(1, -0.5);
	j_hat = createVector(-0.1, 0.5);
	k_hat = createVector(0, -1);

	/*
		// i tried to implement it going fullscreen when 'fullscreen=true' is passed in the url but couldnt figure it out :/
		const params = new URLSearchParams(window.location.search);
		console.log(params);
	*/

	calcGridSize()

	createCanvas(windowWidth, windowHeight);
	frameRate(24);

	for(let y = - cellsY; y < cellsY * 2; y++) {
	//for(let y = 0; y < cellsY; y++) {
		for(let x = -cellsX; x < cellsX * 2; x++) {
			if(random() > 0.5) {
				continue;
			}

			let triggerPoint = map(random(), 0, 1, - width / 3, width / 8);
			let col = getRandColIndex();
			squares.push({
				x: x - floor(cellsX * 2.5), // left right in plane
				y: y - floor(cellsY * 0.5), // up down in plane
				z: 0, // height 'above'/'below' plane
				t: 0,
				triggerPoint: triggerPoint,
				theta: 0,
				riseRange: [0, 1],
				flipRange: [1, 2.3],
				fallRange: [2.5, 4.5],
				col: col,
			})
		} 
	}
}

function calcGridSize() {
	cellsX = ceil(windowWidth / cellSize);
	cellsY = ceil(windowHeight / cellSize);
}

function getRandColIndex() {
	return floor(map(random(), 0, 1, 0, colors_dark.length));
}

function draw() {	


	translate(width / 2, height / 2)

	offsetX += deltaTime * 0.0005;

	/*
	i_hat.x = i_hat_x + 1.0;
	i_hat.y = i_hat_y;
	j_hat.x = j_hat_x;
	j_hat.y = j_hat_y + 1.0;*/
	background(background_dark);


	stroke(background_light);
	strokeWeight(2)
	//drawGrid()
	for(let i = 0; i < squares.length; i++) {
		updateSquare(squares[i])
		drawSquare(squares[i])
	}
}

function drawGrid() {
	stroke(background_light);
	strokeWeight(2);
	noFill();

	for(let y = -cellsY * 2; y < cellsY * 2; y++) {
		let t = map(y, 0, cellsY, 0, cellsY * cellSize)
		let p1 = skewPoint(createVector(-width * 2 + fract(offsetX) * cellSize, t + fract(offsetY) * cellSize));
		let p2 = skewPoint(createVector(width * 2 + fract(offsetX) * cellSize, t + fract(offsetY) * cellSize));

		line(p1.x, p1.y, p2.x, p2.y)
	}

	for(let x = -cellsX * 2; x < cellsX * 2; x++) {
		let t = map(x, 0, cellsX, 0, cellsX * cellSize);
		let p1 = skewPoint(createVector(t + fract(offsetX) * cellSize, -height * 2 + fract(offsetY) * cellSize));
		let p2 = skewPoint(createVector(t + fract(offsetX) * cellSize, height * 2 + fract(offsetY) * cellSize));

		line(p1.x, p1.y, p2.x, p2.y)
	}
}

function updateSquare(square) {
	let posX = skewPoint(createVector((square.x + offsetX + 0.5) * cellSize, (square.y + offsetY + 0.5) * cellSize)).x
	if (posX > square.triggerPoint) {
		square.t += deltaTime * 0.001;
	}


	if (posX > width) {
		square.x -= cellsX * 3;
		square.t = 0;
		square.col = getRandColIndex();
		square.theta = 0;
	}

	square.z = easeInOutSine(map(square.t, square.riseRange[0], square.riseRange[1], 0, 1, true));
	square.theta = easeInOutBack(map(square.t, square.flipRange[0], square.flipRange[1], 0, 1, true)) * PI;

	if(square.t >= square.fallRange[0]) {
		square.z = easeInOutSine(map(square.t, square.fallRange[0], square.fallRange[1], 1, 0, true));
	}
}

function drawSquare(square) {
	let verts = getSquareVerts(createVector(square.x + offsetX + 0.5, square.y + offsetY + 0.5), square.theta)

	let dir = skewPoint3d(p5.Vector.fromAngle(square.theta));
	let dir2 = skewPoint(createVector(0, -1));

	let angle = p5.Vector.angleBetween(dir, dir2)

	if(angle < 0) {
		noFill();
	} else {
		fill(colors_dark[square.col]);
	}


	beginShape();
	for(let i = 0; i < 4; i++) {
		vertex(verts[i].x, verts[i].y - square.z * cellSize);
	}
	endShape(CLOSE);
}

// returns the vertices of the square centered on center and rotated by theta 
function getSquareVerts(center, theta) {
	let p1 = skewPoint(createVector(center.x * cellSize, (center.y - 0.5) * cellSize));
	let p2 = skewPoint(createVector(center.x * cellSize, (center.y + 0.5) * cellSize));

	let dir = skewPoint3d(p5.Vector.fromAngle(theta).mult(cellSize * 0.5));

	//return order is the top left, top right, bottom right, bottom left corner
	return [{x: p1.x - dir.x, y: p1.y - dir.y}, {x: p1.x + dir.x, y: p1.y + dir.y}, {x: p2.x + dir.x, y: p2.y + dir.y}, {x: p2.x - dir.x, y: p2.y - dir.y}]
}

//function that skews a 2d vector to achieve the pseudo orthographic 3d effect
function skewPoint(vec) {
	let skewedX = vec.x * i_hat.x + vec.y * i_hat.y;
	let skewedY = vec.x * j_hat.x + vec.y * j_hat.y;

	return createVector(skewedX, skewedY);
}

// special function that allows the effect of flipping the square to look right.
// it uses the vector k_hat to lerp the vector in the pseudo 3rd dimension (which is just a vector pointing up)
function skewPoint3d(vec) {
	let skewedX = vec.x * i_hat.x + vec.y * k_hat.x;
	let skewedY = vec.x * j_hat.x + vec.y * k_hat.y;

	return createVector(skewedX, skewedY);
}

// Resize the canvas when the
// browser's size changes.
function windowResized() {
	//calcGridSize();
	resizeCanvas(windowWidth, windowHeight);
}

function mousePressed() {

	if(fullscreen()) {
		noCursor();
	} else {
		cursor();
	}
	if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0 && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > 0 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < height) {
		let fs = fullscreen();
	   fullscreen(!fs);
	}
}

function easeInOutSine(x) {
	return -(Math.cos(Math.PI * x) - 1) / 2;
}


// functions taken from https://easings.net/
function easeOutElastic(x) {
const c4 = (2 * Math.PI) / 3;
	return x === 0 ? 0 : x === 1 ? 1 : Math.pow(2, -10 * x) * Math.sin((x * 10 - 0.75) * c4) + 1;
}

function easeInElastic(x) {
	const c4 = (2 * Math.PI) / 3;
	return x === 0 ? 0 : x === 1 ? 1 : -Math.pow(2, 10 * x - 10) * Math.sin((x * 10 - 10.75) * c4);
}

function easeInOutBack(x) {
	const c1 = 1.70158;
	const c2 = c1 * 1.525;

	return x < 0.5 ? (Math.pow(2 * x, 2) * ((c2 + 1) * 2 * x - c2)) / 2 : (Math.pow(2 * x - 2, 2) * ((c2 + 1) * (x * 2 - 2) + c2) + 2) / 2;
}

function easeOutExpo(x) {
	return x === 1 ? 1 : 1 - Math.pow(2, -10 * x);
}
